  .delete-btn:focus-visible {
    outline-color: CanvasText;
  }

  .dialog-content,
  .dialog-actions {
    background-color: Canvas;
    color: CanvasText;
  }

  dialog::backdrop {
    background-color: Canvas;
  }
}
