const fs = require('fs');
const path = require('path');
const axeSource = fs.readFileSync('/tmp/axe.min.js', 'utf8');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Load the HTML file
  const htmlPath = path.join(__dirname, 'index.html');
  const html = fs.readFileSync(htmlPath, 'utf8');

  // Set content and wait for load
  await page.setContent(html, { waitUntil: 'load' });

  // Wait for any script execution
  await page.waitForTimeout(500);

  // Inject axe-core and run
  await page.evaluate(axeSource);
  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  await browser.close();

  // Separate WCAG violations from best-practice
  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  // Output results
  console.log(JSON.stringify({
    wcag: wcag.map(v => ({
      id: v.id,
      impact: v.impact,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    })),
    bp: bp.map(v => ({
      id: v.id,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    }))
  }, null, 2));

  process.exit(wcag.length > 0 ? 1 : 0);
})().catch(err => {
  console.error('Test error:', err.message);
  process.exit(1);
});

