', direction=None, fact=None, file_name='/workspace/sandbox/skills/building-accessible-ui/modal-dialog--framework-react--style-dark/claude-haiku-4.5__s0/test-a11y-detailed.js', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Edit file', new_file_contents='const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');
const axeSource = fs.readFileSync('/tmp/axe.min.js', 'utf8');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  const htmlPath = path.join(__dirname, 'index.html');
  const html = fs.readFileSync(htmlPath, 'utf8');

  await page.setContent(html, { waitUntil: 'load' });
  await page.waitForTimeout(500);

  // Inject axe-core
  await page.evaluate(axeSource);

  // Test 1: Initial page state
  console.log('=== Test 1: Initial Page State ===');
  let results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  let wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  let bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log(`✓ WCAG violations: ${wcag.length}`);
  console.log(`✓ Best-practice issues: ${bp.length}`);

  // Test 2: Verify trigger buttons exist and have correct class
  console.log('\n=== Test 2: Trigger Button Verification ===');
  const triggerCount = await page.evaluate(() => {
    return document.querySelectorAll('.trigger').length;
  });
  console.log(`✓ Found ${triggerCount} trigger buttons with class="trigger"`);

  // Test 3: Dialog initially closed
  console.log('\n=== Test 3: Dialog Initial State ===');
  const dialogInitiallyClosed = await page.evaluate(() => {
    return !document.querySelector('dialog').open;
  });
  console.log(`✓ Dialog closed on page load: ${dialogInitiallyClosed}`);

  // Test 4: Click trigger to open dialog
  console.log('\n=== Test 4: Dialog Open on Trigger Click ===');
  await page.click('.trigger');
  await page.waitForTimeout(500);

  const dialogOpenAfterClick = await page.evaluate(() => {
    return document.querySelector('dialog').open;
  });
  console.log(`✓ Dialog opens on trigger click: ${dialogOpenAfterClick}`);

  // Test 5: Check focus after dialog open
  console.log('\n=== Test 5: Focus After Dialog Open ===');
  const focusedButton = await page.evaluate(() => {
    const active = document.activeElement;
    return {
      tag: active.tagName,
      text: active.textContent.trim(),
      hasDataClose: active.hasAttribute('data-close')
    };
  });
  console.log(`✓ Focus on: <${focusedButton.tag}> "${focusedButton.text}"`);
  console.log(`✓ Focus on Cancel button (safe default): ${focusedButton.hasDataClose}`);

  // Test 6: Run axe with dialog open
  console.log('\n=== Test 6: Dialog Open State (axe check) ===');
  results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log(`✓ WCAG violations: ${wcag.length}`);
  console.log(`✓ Best-practice issues: ${bp.length}`);

  if (wcag.length > 0) {
    console.log('\nWCAG Issues:');
    wcag.forEach(v => {
      console.log(`  - ${v.id} (${v.impact}): ${v.description}`);
      v.nodes.forEach(n => console.log(`    ${n.target}`));
    });
  }

  if (bp.length > 0) {
    console.log('\nBest-practice Issues:');
    bp.forEach(v => {
      console.log(`  - ${v.id}: ${v.description}`);
      v.nodes.forEach(n => console.log(`    ${n.target}`));
    });
  }

  // Test 7: Escape key closes dialog
  console.log('\n=== Test 7: Escape Key Handler ===');
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);

  const dialogClosedByEscape = await page.evaluate(() => {
    return !document.querySelector('dialog').open;
  });
  console.log(`✓ Escape key closes dialog: ${dialogClosedByEscape}`);

  // Test 8: Verify focus restoration
  console.log('\n=== Test 8: Focus Restoration After Close ===');
  const focusAfterClose = await page.evaluate(() => {
    const active = document.activeElement;
    return active.classList.contains('trigger');
  });
  console.log(`✓ Focus restored to trigger button: ${focusAfterClose}`);

  // Test 9: Aria attributes
  console.log('\n=== Test 9: ARIA Attributes ===');
  const ariaCheck = await page.evaluate(() => {
    const dialog = document.querySelector('dialog');
    const heading = document.querySelector('#delete-dialog-heading');
    return {
      dialogHasAriaLabelledby: dialog.hasAttribute('aria-labelledby'),
      ariaLabelledbyValue: dialog.getAttribute('aria-labelledby'),
      headingExists: !!heading,
      headingId: heading ? heading.id : null
    };
  });

  console.log(`✓ Dialog has aria-labelledby: ${ariaCheck.dialogHasAriaLabelledby}`);
  console.log(`✓ aria-labelledby value: "${ariaCheck.ariaLabelledbyValue}"`);
  console.log(`✓ Heading exists: ${ariaCheck.headingExists}`);
  console.log(`✓ IDs match: ${ariaCheck.ariaLabelledbyValue === ariaCheck.headingId}`);

  // Test 10: Image alt text
  console.log('\n=== Test 10: Image Alt Text ===');
  const imageAltCheck = await page.evaluate(() => {
    const images = Array.from(document.querySelectorAll('img'));
    return {
      totalImages: images.length,
      withAlt: images.filter(img => img.hasAttribute('alt') && img.getAttribute('alt').length > 0).length,
      descriptions: images.map(img => img.getAttribute('alt'))
    };
  });

  console.log(`✓ Total images: ${imageAltCheck.totalImages}`);
  console.log(`✓ Images with alt text: ${imageAltCheck.withAlt}`);
  console.log(`✓ Alt text examples: ${imageAltCheck.descriptions.slice(0, 2).join(', ')}`);

  await browser.close();

  console.log('\n=== All Tests Complete ✓ ===');
})().catch(err => {
  console.error('Test error:', err.message);
  console.error(err.stack);
  process.exit(1);
});
