function initializeDialog() {
  const dialog = document.getElementById('delete-dialog');
  const triggers = document.querySelectorAll('.trigger');
  let currentTrigger = null;

  /**
   * Open dialog and manage focus
   */
  function openDialog(trigger) {
    currentTrigger = trigger;
    dialog.showModal();

    // Move focus to the cancel button (not the dangerous delete action)
    const cancelButton = dialog.querySelector('[data-close]');
    if (cancelButton) {
      cancelButton.focus();
    }
  }

  /**
   * Close dialog and restore focus
   */
  function closeDialog() {
    dialog.close();

    // Restore focus to the trigger that opened the dialog
    if (currentTrigger && document.contains(currentTrigger)) {
      currentTrigger.focus();
    }
    currentTrigger = null;
  }

  /**
   * Handle dialog close action (Cancel button)
   */
  function handleCancel() {
    closeDialog();
  }

  /**
   * Handle dialog confirm action (Delete button)
   */
  function handleConfirm() {
    // In a real application, this would trigger the deletion logic
    console.log('Image deletion confirmed');
    closeDialog();
  }

  /**
   * Handle Escape key press to close dialog
   */
  function handleEscapeKey(event) {
    if (event.key === 'Escape') {
      closeDialog();
    }
  }

  // Attach click handlers to all trigger buttons
  triggers.forEach(trigger => {
    trigger.addEventListener('click', () => openDialog(trigger));
  });

  // Attach close button handler
  const closeButton = dialog.querySelector('[data-close]');
  if (closeButton) {
    closeButton.addEventListener('click', handleCancel);
  }

  // Attach confirm button handler
  const confirmButton = dialog.querySelector('[data-confirm]');
  if (confirmButton) {
    confirmButton.addEventListener('click', handleConfirm);
  }

  // Handle Escape key
  dialog.addEventListener('keydown', handleEscapeKey);

  // Fallback for browsers that don't fully support <dialog> yet
  // Ensures Escape key closes the dialog in all scenarios
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape' && dialog.open) {
      closeDialog();
    }
  });
}

// Initialize when DOM is ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initializeDialog);
} else {
  initializeDialog();
}

